def find_magic_sequence(n):
    # We need to find x[0], ..., x[n-1] such that x[i] = count of i in the sequence
    # Constraints:
    # 1. sum(x) = n
    # 2. sum(i * x[i] for i in range(n)) = n
    # 3. x[i] >= 0 for all i
    # 4. x[i] = count of i in the sequence

    # Let's use a constraint solver approach
    from itertools import product

    # For n=7, we can try all possible sequences where sum(x) = 7
    # But that's still a lot. Let's use a smarter approach.

    # Actually, let's use a simple backtracking search
    def solve(idx, current_seq, counts):
        if idx == n:
            # Check if the sequence is valid
            for i in range(n):
                if current_seq[i] != counts[i]:
                    return None
            return current_seq

        # Try all possible values for x[idx]
        # x[idx] can be at most n - sum(current_seq[:idx])
        remaining = n - sum(current_seq[:idx])
        for val in range(remaining + 1):
            current_seq[idx] = val
            counts[val] += 1
            result = solve(idx + 1, current_seq, counts)
            counts[val] -= 1
            if result is not None:
                return result
        return None

    # This approach is too slow. Let's use a different method.
    # We know that sum(x) = n and sum(i*x[i]) = n
    # Let's enumerate all partitions of n into n parts

    def solve2():
        # Use dynamic programming or direct enumeration
        # For n=7, we can enumerate all sequences where sum(x) = 7
        # and check the constraints

        def generate_sequences(n, length, current_sum):
            if length == 0:
                if current_sum == 0:
                    yield []
                return
            for val in range(current_sum + 1):
                for rest in generate_sequences(n, length - 1, current_sum - val):
                    yield [val] + rest

        for seq in generate_sequences(7, 7, 7):
            # Check if sum(i * x[i]) = 7
            weighted_sum = sum(i * seq[i] for i in range(7))
            if weighted_sum != 7:
                continue

            # Check if x[i] = count of i in seq
            counts = [0] * 7
            for val in seq:
                if val < 7:
                    counts[val] += 1

            if all(seq[i] == counts[i] for i in range(7)):
                return seq

        return None

    return solve2()

result = find_magic_sequence(7)
print(f"Result: {result}")
